-- Desired schema of the emergency bounded context (declarative). See ADR-0006,
-- ADR-0009 and ADR-0019. SOS texts, child cards and external contacts' names
-- and phones are sealed with the owner's data key; members are IDs only.
-- Rows are never deleted: SOS requests are closed, trusted contacts removed
-- (removed_at), so the only deletion paths are the account-deletion flow and
-- the retention of expired plan and SOS links (ADR-0023: 7 days after expiry).

CREATE SCHEMA IF NOT EXISTS emergency;

-- One SOS request. The id is generated by the service before sealing, because
-- the text's associated data names the row (emergency.sos.text|<id>).
CREATE TABLE emergency.sos_requests (
    id              uuid        PRIMARY KEY,
    member_id       uuid        NOT NULL,
    idempotency_key uuid        NOT NULL,
    type            text        NOT NULL
                                CHECK (type IN ('childcare', 'item_or_medicine', 'other')),
    -- Personal data: the SOS text, sealed with associated data
    -- emergency.sos.text|<id> (the AD field name predates the column name;
    -- it is part of the schema and must not change).
    content         bytea       NOT NULL CHECK (octet_length(content) BETWEEN 1 AND 4096),
    status          text        NOT NULL DEFAULT 'open'
                                CHECK (status IN ('open', 'closed')),
    created_at      timestamptz NOT NULL,
    closes_at       timestamptz NOT NULL,
    -- Set together when the author shares the request to her district feed.
    district_id     uuid,
    shared_at       timestamptz,
    closed_at       timestamptz,
    close_reason    text        CHECK (close_reason IN ('author', 'auto')),
    -- Moderator queue (requirements section 6): the first staff member who
    -- pressed "Seen" and when; later presses keep the first. Staff IDs, not
    -- member data.
    seen_at         timestamptz,
    seen_by         uuid,
    -- Staff ID when a moderator closed the request. close_reason is then
    -- 'author' (closed by a person, not by the timer): the reason check
    -- predates staff closing, and widening it is a constraint swap that the
    -- migration gate treats as destructive. closed_by tells the two apart.
    closed_by       uuid,
    CONSTRAINT sos_requests_closes_check CHECK (closes_at > created_at),
    CONSTRAINT sos_requests_shared_check CHECK ((district_id IS NULL) = (shared_at IS NULL)),
    -- N5 (AGENTS.md non-negotiable 5): a childcare request never reaches the
    -- district feed, only moderators and confirmed trusted contacts.
    CONSTRAINT sos_requests_childcare_never_shared CHECK (type <> 'childcare' OR shared_at IS NULL),
    CONSTRAINT sos_requests_lifecycle_check CHECK (
        (status = 'open' AND closed_at IS NULL AND close_reason IS NULL)
        OR (status = 'closed' AND closed_at IS NOT NULL AND close_reason IS NOT NULL)
    ),
    CONSTRAINT sos_requests_seen_check CHECK ((seen_at IS NULL) = (seen_by IS NULL)),
    CONSTRAINT sos_requests_closed_by_check CHECK (
        closed_by IS NULL OR (status = 'closed' AND close_reason = 'author')
    )
);

-- Repeated raises with the same Idempotency-Key have one effect.
CREATE UNIQUE INDEX sos_requests_member_idempotency_uidx
    ON emergency.sos_requests (member_id, idempotency_key);
-- Rate limit (3 per hour) and "my SOS", newest first.
CREATE INDEX sos_requests_member_created_idx
    ON emergency.sos_requests (member_id, created_at DESC, id DESC);
-- District feed: open, shared, never childcare.
CREATE INDEX sos_requests_feed_idx
    ON emergency.sos_requests (district_id, created_at DESC, id DESC)
    WHERE status = 'open' AND shared_at IS NOT NULL AND type <> 'childcare';
-- Moderator queue: open requests oldest first, closed ones newest first
-- (the same index read backwards).
CREATE INDEX sos_requests_staff_queue_idx
    ON emergency.sos_requests (status, created_at, id);

-- "I can help" from a member of the district; one per responder and request.
CREATE TABLE emergency.sos_responses (
    id           uuid        PRIMARY KEY DEFAULT uuidv7(),
    sos_id       uuid        NOT NULL REFERENCES emergency.sos_requests (id),
    responder_id uuid        NOT NULL,
    created_at   timestamptz NOT NULL,
    -- Set when the author chose this responder (chat opens a private room).
    accepted_at  timestamptz,
    CONSTRAINT sos_responses_sos_responder_key UNIQUE (sos_id, responder_id)
);

CREATE INDEX sos_responses_sos_created_idx
    ON emergency.sos_responses (sos_id, created_at ASC, id ASC);

-- The child card of the emergency plan, one per member.
CREATE TABLE emergency.child_cards (
    member_id    uuid        PRIMARY KEY,
    -- Personal data: sealed with associated data emergency.child_cards.text|<member id>
    -- (AD field name fixed; see sos_requests.content).
    content      bytea       NOT NULL CHECK (octet_length(content) BETWEEN 1 AND 16384),
    updated_at   timestamptz NOT NULL,
    last_sent_at timestamptz
);

-- Up to three trusted contacts per member (invited + confirmed, enforced by
-- the service under a per-owner lock). A member contact must have met the
-- owner in person and accept the invitation; an external contact is
-- confirmed when added and has a sealed name and phone.
CREATE TABLE emergency.trusted_contacts (
    id                uuid        PRIMARY KEY,
    owner_id          uuid        NOT NULL,
    idempotency_key   uuid        NOT NULL,
    kind              text        NOT NULL CHECK (kind IN ('member', 'external')),
    contact_member_id uuid,
    -- Personal data: sealed with the owner's key, associated data
    -- emergency.trusted_contacts.name|<id> and emergency.trusted_contacts.phone|<id>.
    name              bytea       CHECK (octet_length(name) <= 1024),
    phone             bytea       CHECK (octet_length(phone) <= 1024),
    -- Language of SMS to an external contact (the owner's language when added).
    lang              text        NOT NULL CHECK (lang IN ('kk', 'ru')),
    status            text        NOT NULL CHECK (status IN ('invited', 'confirmed')),
    created_at        timestamptz NOT NULL,
    confirmed_at      timestamptz,
    -- Set when the owner sent the plan while this contact was confirmed;
    -- getSharedPlan is allowed only after that.
    plan_sent_at      timestamptz,
    removed_at        timestamptz,
    CONSTRAINT trusted_contacts_kind_fields_check CHECK (
        (kind = 'member' AND contact_member_id IS NOT NULL AND name IS NULL AND phone IS NULL)
        OR (kind = 'external' AND contact_member_id IS NULL AND name IS NOT NULL AND phone IS NOT NULL
            AND status = 'confirmed')
    ),
    CONSTRAINT trusted_contacts_confirmed_check CHECK ((status = 'confirmed') = (confirmed_at IS NOT NULL)),
    CONSTRAINT trusted_contacts_self_check CHECK (contact_member_id IS NULL OR contact_member_id <> owner_id)
);

CREATE UNIQUE INDEX trusted_contacts_owner_idempotency_uidx
    ON emergency.trusted_contacts (owner_id, idempotency_key);
-- A member is at most one active contact of the same owner.
CREATE UNIQUE INDEX trusted_contacts_owner_member_uidx
    ON emergency.trusted_contacts (owner_id, contact_member_id)
    WHERE removed_at IS NULL AND kind = 'member';
CREATE INDEX trusted_contacts_owner_active_idx
    ON emergency.trusted_contacts (owner_id, created_at ASC, id ASC) WHERE removed_at IS NULL;

-- One row per "send the plan" confirmation (Idempotency-Key); also the rate
-- limit for plan sends, which reach external contacts by SMS.
CREATE TABLE emergency.plan_sends (
    id              uuid        PRIMARY KEY,
    member_id       uuid        NOT NULL,
    idempotency_key uuid        NOT NULL,
    contact_count   integer     NOT NULL CHECK (contact_count BETWEEN 1 AND 3),
    sent_at         timestamptz NOT NULL
);

CREATE UNIQUE INDEX plan_sends_member_idempotency_uidx
    ON emergency.plan_sends (member_id, idempotency_key);
CREATE INDEX plan_sends_member_sent_idx
    ON emergency.plan_sends (member_id, sent_at DESC);

-- One-time links to the child card for external trusted contacts (no
-- account), sent in the plan SMS as <public URL>/plan#<token>. The token
-- itself is never stored: only HMAC-SHA256(BIRGE_PLAN_LINK_KEY_FILE, token),
-- so a database dump cannot open a plan. A link lives 24 hours from the plan
-- send (expires_at = sent_at + 24h) and is revoked earlier when the owner
-- sends again, removes the contact or mints a new link for the contact. The
-- emergency.PlanLinkPurge timer deletes the row 7 days after expires_at
-- (ADR-0023); nothing refers to it, so no tombstone is kept.
CREATE TABLE emergency.plan_links (
    id         uuid        PRIMARY KEY,
    token_hash bytea       NOT NULL CHECK (octet_length(token_hash) = 32),
    contact_id uuid        NOT NULL REFERENCES emergency.trusted_contacts (id),
    owner_id   uuid        NOT NULL,
    -- The plan send this link belongs to (trusted_contacts.plan_sent_at at mint time).
    sent_at    timestamptz NOT NULL,
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    CONSTRAINT plan_links_expiry_check CHECK (expires_at > sent_at)
);

-- The lookup of viewExternalPlan, by keyed hash only.
CREATE UNIQUE INDEX plan_links_token_hash_uidx ON emergency.plan_links (token_hash);
-- Revocation per contact (resend, removal, new link).
CREATE INDEX plan_links_contact_active_idx
    ON emergency.plan_links (contact_id) WHERE revoked_at IS NULL;
-- Revocation on resend and account deletion per owner.
CREATE INDEX plan_links_owner_idx ON emergency.plan_links (owner_id);

-- Links to an open SOS for external trusted contacts (no account), sent in
-- the SOS SMS as <public URL>/sos-link#<token> (viewExternalSos). A table of its
-- own rather than a kind column on plan_links: the two differ in what keeps
-- them alive (the plan send against the SOS being open), in what revokes
-- them and in what they open, and every plan_links query would otherwise
-- need a kind filter whose omission would let one kind open the other. The
-- token is never stored: only HMAC-SHA256(BIRGE_PLAN_LINK_KEY_FILE,
-- "emergency.sos_link|" || token), a different input from the plan link
-- hash, so a plan token never matches here and the reverse. A link lives
-- until the SOS closes and at most 24 hours from the SOS (expires_at =
-- least(closes_at, created_at + 24h)); viewExternalSos also re-checks the
-- SOS (open) and the contact (active, external, confirmed, still the
-- author's) in its single lookup. A newer link for the same SOS and contact
-- (a retried SMS) revokes the older one. The emergency.SosLinkPurge timer
-- deletes the row 7 days after expires_at (ADR-0023); nothing refers to it,
-- so no tombstone is kept.
CREATE TABLE emergency.sos_links (
    id         uuid        PRIMARY KEY,
    token_hash bytea       NOT NULL CHECK (octet_length(token_hash) = 32),
    sos_id     uuid        NOT NULL REFERENCES emergency.sos_requests (id),
    contact_id uuid        NOT NULL REFERENCES emergency.trusted_contacts (id),
    -- The SOS author, who is also the contact's owner.
    owner_id   uuid        NOT NULL,
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    CONSTRAINT sos_links_expiry_check CHECK (expires_at > created_at)
);

-- The lookup of viewExternalSos, by keyed hash only.
CREATE UNIQUE INDEX sos_links_token_hash_uidx ON emergency.sos_links (token_hash);
-- Revocation of an earlier link of the same SOS and contact.
CREATE INDEX sos_links_sos_contact_active_idx
    ON emergency.sos_links (sos_id, contact_id) WHERE revoked_at IS NULL;
-- Account deletion per owner.
CREATE INDEX sos_links_owner_idx ON emergency.sos_links (owner_id);
